  1→package agents
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"os/exec"
 10→	"path/filepath"
 11→	"regexp"
 12→	"strconv"
 13→	"strings"
 14→	"syscall"
 15→	"time"
 16→)
 17→
 18→func init() {
 19→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "factoryai-droid" {
 20→		return
 21→	}
 22→	if _, err := exec.LookPath("droid"); err != nil {
 23→		return
 24→	}
 25→	Register(&Droid{})
 26→	RegisterGate("factoryai-droid", 2)
 27→}
 28→
 29→// Droid implements the Agent interface for Factory AI Droid.
 30→type Droid struct{}
 31→
 32→func (d *Droid) Name() string               { return "factoryai-droid" }
 33→func (d *Droid) Binary() string             { return "droid" }
 34→func (d *Droid) EntireAgent() string        { return "factoryai-droid" }
 35→func (d *Droid) PromptPattern() string      { return `ENTER to send` }
 36→func (d *Droid) TimeoutMultiplier() float64 { return 2.0 }
 37→
 38→func (d *Droid) IsTransientError(out Output, err error) bool {
 39→	if err == nil {
 40→		return false
 41→	}
 42→	combined := out.Stdout + out.Stderr
 43→	transientPatterns := []string{
 44→		"overloaded",
 45→		"rate limit",
 46→		"529",
 47→		"503",
 48→		"ECONNRESET",
 49→		"ETIMEDOUT",
 50→	}
 51→	for _, p := range transientPatterns {
 52→		if strings.Contains(combined, p) {
 53→			return true
 54→		}
 55→	}
 56→	return false
 57→}
 58→
 59→// droidSettings represents the ~/.factory/settings.json structure used for
 60→// BYOK (Bring Your Own Key) configuration and session defaults.
 61→type droidSettings struct {
 62→	CustomModels           []droidCustomModel    `json:"customModels,omitempty"`
 63→	SessionDefaultSettings *droidSessionDefaults `json:"sessionDefaultSettings,omitempty"`
 64→}
 65→
 66→type droidCustomModel struct {
 67→	DisplayName    string `json:"displayName"`
 68→	Model          string `json:"model"`
 69→	BaseURL        string `json:"baseUrl"`
 70→	APIKey         string `json:"apiKey"`
 71→	Provider       string `json:"provider"`
 72→	MaxOutputToken int    `json:"maxOutputTokens"`
 73→}
 74→
 75→// droidSessionDefaults configures interactive-mode defaults (model, autonomy, etc.).
 76→type droidSessionDefaults struct {
 77→	Model           string `json:"model,omitempty"`
 78→	AutonomyMode    string `json:"autonomyMode,omitempty"`
 79→	ReasoningEffort string `json:"reasoningEffort,omitempty"`
 80→}
 81→
 82→const (
 83→	// Droid v0.63+ expects custom model selection using custom:<model-id>.
 84→	// The displayName in settings is not accepted by --model.
 85→	droidCustomModelDisplayName = "claude-haiku-custom"
 86→	droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
 87→	defaultDroidModel           = "custom:" + droidCustomModelBaseID
 88→)
 89→
 90→type droidStartupConfig struct {
 91→	attempts          int
 92→	timeout           time.Duration
 93→	warmup            bool
 94→	handshakeTimeout  time.Duration
 95→	handshakeAttempts int
 96→	handshakeRestarts int
 97→}
 98→
 99→func droidStartupConfigFromEnv() droidStartupConfig {
100→	cfg := droidStartupConfig{
101→		attempts:          2,
102→		timeout:           60 * time.Second,
103→		warmup:            false,
104→		handshakeTimeout:  45 * time.Second,
105→		handshakeAttempts: 2,
106→		handshakeRestarts: 1,
107→	}
108→
109→	if os.Getenv("CI") != "" {
110→		cfg.attempts = 3
111→		cfg.timeout = 90 * time.Second
112→		cfg.warmup = true
113→	}
114→
115→	if raw := os.Getenv("E2E_DROID_STARTUP_ATTEMPTS"); raw != "" {
116→		if v, err := strconv.Atoi(raw); err == nil && v > 0 {
117→			cfg.attempts = v
118→		}
119→	}
120→	if raw := os.Getenv("E2E_DROID_STARTUP_TIMEOUT"); raw != "" {
121→		if v, err := time.ParseDuration(raw); err == nil && v > 0 {
122→			cfg.timeout = v
123→		}
124→	}
125→	if raw := os.Getenv("E2E_DROID_WARMUP"); raw != "" {
126→		switch strings.ToLower(strings.TrimSpace(raw)) {
127→		case "0", "false", "off", "no":
128→			cfg.warmup = false
129→		case "1", "true", "on", "yes":
130→			cfg.warmup = true
131→		}
132→	}
133→	if raw := os.Getenv("E2E_DROID_HANDSHAKE_TIMEOUT"); raw != "" {
134→		if v, err := time.ParseDuration(raw); err == nil && v > 0 {
135→			cfg.handshakeTimeout = v
136→		}
137→	}
138→	if raw := os.Getenv("E2E_DROID_HANDSHAKE_ATTEMPTS"); raw != "" {
139→		if v, err := strconv.Atoi(raw); err == nil && v > 0 {
140→			cfg.handshakeAttempts = v
141→		}
142→	}
143→	if raw := os.Getenv("E2E_DROID_HANDSHAKE_RESTARTS"); raw != "" {
144→		if v, err := strconv.Atoi(raw); err == nil && v >= 0 {
145→			cfg.handshakeRestarts = v
146→		}
147→	}
148→
149→	return cfg
150→}
151→
152→func droidStartupReadyPattern() string {
153→	return `(?s)(ENTER to send.*Current folder:|Current folder:.*ENTER to send)`
154→}
155→
156→func droidPromptReady(content string) bool {
157→	return strings.Contains(content, "ENTER to send") ||
158→		strings.Contains(content, "│ >") ||
159→		strings.Contains(content, "| >")
160→}
161→
162→func droidStartupMarkersReady(content string) bool {
163→	return strings.Contains(content, "ENTER to send") &&
164→		strings.Contains(content, "Current folder:")
165→}
166→
167→func droidHandshakeToken() string {
168→	return fmt.Sprintf("ENTIRE_E2E_READY_%d", time.Now().UnixNano())
169→}
170→
171→func droidHandshakePrompt(token string) string {
172→	return "E2E handshake check. Reply with exactly this token and nothing else: " + token +
173→		". Do not edit files, run commands, or commit."
174→}
175→
176→func (d *Droid) Bootstrap() error {
177→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
178→	if apiKey != "" {
179→		home, err := os.UserHomeDir()
180→		if err != nil {
181→			return fmt.Errorf("get home dir: %w", err)
182→		}
183→		dir := filepath.Join(home, ".factory")
184→		if err := os.MkdirAll(dir, 0o755); err != nil {
185→			return fmt.Errorf("mkdir %s: %w", dir, err)
186→		}
187→
188→		settingsPath := filepath.Join(dir, "settings.json")
189→
190→		// Read existing settings to merge (hooks may already be configured
191→		// in the repo-local .factory/settings.json, but the global config
192→		// at ~/.factory/settings.json might have other pre-existing entries).
193→		var settings droidSettings
194→		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
195→			// Best-effort merge: ignore parse errors and start fresh
196→			_ = json.Unmarshal(data, &settings)
197→		}
198→
199→		// Replace or add the BYOK model entry.
200→		byokModel := droidCustomModel{
201→			DisplayName:    droidCustomModelDisplayName,
202→			Model:          droidCustomModelBaseID,
203→			BaseURL:        "https://api.anthropic.com",
204→			APIKey:         apiKey,
205→			Provider:       "anthropic",
206→			MaxOutputToken: 8192,
207→		}
208→
209→		found := false
210→		for i, m := range settings.CustomModels {
211→			if m.Model == byokModel.Model {
212→				settings.CustomModels[i] = byokModel
213→				found = true
214→				break
215→			}
216→		}
217→		if !found {
218→			settings.CustomModels = append(settings.CustomModels, byokModel)
219→		}
220→
221→		// Set the BYOK model as the default for interactive mode.
222→		if settings.SessionDefaultSettings == nil {
223→			settings.SessionDefaultSettings = &droidSessionDefaults{}
224→		}
225→		settings.SessionDefaultSettings.Model = droidCustomModelBaseID
226→
227→		data, err := json.MarshalIndent(settings, "", "  ")
228→		if err != nil {
229→			return fmt.Errorf("marshal settings: %w", err)
230→		}
231→		if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
232→			return fmt.Errorf("write settings: %w", err)
233→		}
234→	}
235→
236→	cfg := droidStartupConfigFromEnv()
237→	if !cfg.warmup {
238→		return nil
239→	}
240→	if err := d.warmup(); err != nil {
241→		fmt.Fprintf(os.Stderr, "droid warmup failed (non-fatal): %v\n", err)
242→	}
243→	return nil
244→}
245→
246→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
247→	cfg := &runConfig{Model: defaultDroidModel}
248→	for _, o := range opts {
249→		o(cfg)
250→	}
251→
252→	model := cfg.Model
253→	if model == "" {
254→		model = defaultDroidModel
255→	}
256→
257→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
258→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
259→
260→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
261→	cmd.Dir = dir
262→	cmd.Stdin = nil
263→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
264→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
265→	cmd.Cancel = func() error {
266→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
267→	}
268→	cmd.WaitDelay = 5 * time.Second
269→
270→	var stdout, stderr strings.Builder
271→	cmd.Stdout = &stdout
272→	cmd.Stderr = &stderr
273→
274→	err := cmd.Run()
275→	exitCode := 0
276→	if err != nil {
277→		exitErr := &exec.ExitError{}
278→		if errors.As(err, &exitErr) {
279→			exitCode = exitErr.ExitCode()
280→		} else {
281→			exitCode = -1
282→		}
283→	}
284→
285→	return Output{
286→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
287→		Stdout:   stdout.String(),
288→		Stderr:   stderr.String(),
289→		ExitCode: exitCode,
290→	}, err
291→}
292→
293→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
294→	_ = ctx
295→	cfg := droidStartupConfigFromEnv()
296→
297→	var s *TmuxSession
298→	var lastErr error
299→	handshakeRestartsLeft := cfg.handshakeRestarts
300→	for attempt := range cfg.attempts {
301→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
302→		var err error
303→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
304→		if err != nil {
305→			return nil, err
306→		}
307→
308→		// Resize so droid's full-screen TUI has room to render the prompt area.
309→		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
