package agents

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "factoryai-droid" {
		return
	}
	if _, err := exec.LookPath("droid"); err != nil {
		return
	}
	Register(&Droid{})
	RegisterGate("factoryai-droid", 2)
}

// Droid implements the Agent interface for Factory AI Droid.
type Droid struct{}

func (d *Droid) Name() string               { return "factoryai-droid" }
func (d *Droid) Binary() string             { return "droid" }
func (d *Droid) EntireAgent() string        { return "factoryai-droid" }
func (d *Droid) PromptPattern() string      { return `ENTER to send` }
func (d *Droid) TimeoutMultiplier() float64 { return 2.0 }

func (d *Droid) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	combined := out.Stdout + out.Stderr
	transientPatterns := []string{
		"overloaded",
		"rate limit",
		"529",
		"503",
		"ECONNRESET",
		"ETIMEDOUT",
	}
	for _, p := range transientPatterns {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

// droidSettings represents the ~/.factory/settings.json structure used for
// BYOK (Bring Your Own Key) configuration and session defaults.
type droidSettings struct {
	CustomModels           []droidCustomModel    `json:"customModels,omitempty"`
	SessionDefaultSettings *droidSessionDefaults `json:"sessionDefaultSettings,omitempty"`
}

type droidCustomModel struct {
	DisplayName    string `json:"displayName"`
	Model          string `json:"model"`
	BaseURL        string `json:"baseUrl"`
	APIKey         string `json:"apiKey"`
	Provider       string `json:"provider"`
	MaxOutputToken int    `json:"maxOutputTokens"`
}

// droidSessionDefaults configures interactive-mode defaults (model, autonomy, etc.).
type droidSessionDefaults struct {
	Model           string `json:"model,omitempty"`
	AutonomyMode    string `json:"autonomyMode,omitempty"`
	ReasoningEffort string `json:"reasoningEffort,omitempty"`
}

const (
	// Droid v0.63+ expects custom model selection using custom:<model-id>.
	// The displayName in settings is not accepted by --model.
	droidCustomModelDisplayName = "claude-haiku-custom"
	droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
	defaultDroidModel           = "custom:" + droidCustomModelBaseID
)

type droidStartupConfig struct {
	attempts          int
	timeout           time.Duration
	warmup            bool
	handshakeTimeout  time.Duration
	handshakeAttempts int
	handshakeRestarts int
}

func droidStartupConfigFromEnv() droidStartupConfig {
	cfg := droidStartupConfig{
		attempts:          2,
		timeout:           60 * time.Second,
		warmup:            false,
		handshakeTimeout:  45 * time.Second,
		handshakeAttempts: 2,
		handshakeRestarts: 1,
	}

	if os.Getenv("CI") != "" {
		cfg.attempts = 3
		cfg.timeout = 90 * time.Second
		cfg.warmup = true
	}

	if raw := os.Getenv("E2E_DROID_STARTUP_ATTEMPTS"); raw != "" {
		if v, err := strconv.Atoi(raw); err == nil && v > 0 {
			cfg.attempts = v
		}
	}
	if raw := os.Getenv("E2E_DROID_STARTUP_TIMEOUT"); raw != "" {
		if v, err := time.ParseDuration(raw); err == nil && v > 0 {
			cfg.timeout = v
		}
	}
	if raw := os.Getenv("E2E_DROID_WARMUP"); raw != "" {
		switch strings.ToLower(strings.TrimSpace(raw)) {
		case "0", "false", "off", "no":
			cfg.warmup = false
		case "1", "true", "on", "yes":
			cfg.warmup = true
		}
	}
	if raw := os.Getenv("E2E_DROID_HANDSHAKE_TIMEOUT"); raw != "" {
		if v, err := time.ParseDuration(raw); err == nil && v > 0 {
			cfg.handshakeTimeout = v
		}
	}
	if raw := os.Getenv("E2E_DROID_HANDSHAKE_ATTEMPTS"); raw != "" {
		if v, err := strconv.Atoi(raw); err == nil && v > 0 {
			cfg.handshakeAttempts = v
		}
	}
	if raw := os.Getenv("E2E_DROID_HANDSHAKE_RESTARTS"); raw != "" {
		if v, err := strconv.Atoi(raw); err == nil && v >= 0 {
			cfg.handshakeRestarts = v
		}
	}

	return cfg
}

func droidStartupReadyPattern() string {
	return `(?s)(ENTER to send.*Current folder:|Current folder:.*ENTER to send)`
}

func droidPromptReady(content string) bool {
	return strings.Contains(content, "ENTER to send") ||
		strings.Contains(content, "│ >") ||
		strings.Contains(content, "| >")
}

func droidStartupMarkersReady(content string) bool {
	return strings.Contains(content, "ENTER to send") &&
		strings.Contains(content, "Current folder:")
}

func droidHandshakeToken() string {
	return fmt.Sprintf("ENTIRE_E2E_READY_%d", time.Now().UnixNano())
}

func droidHandshakePrompt(token string) string {
	return "E2E handshake check. Reply with exactly this token and nothing else: " + token +
		". Do not edit files, run commands, or commit."
}

func (d *Droid) Bootstrap() error {
	apiKey := os.Getenv("ANTHROPIC_API_KEY")
	if apiKey != "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return fmt.Errorf("get home dir: %w", err)
		}
		dir := filepath.Join(home, ".factory")
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return fmt.Errorf("mkdir %s: %w", dir, err)
		}

		settingsPath := filepath.Join(dir, "settings.json")

		// Read existing settings to merge (hooks may already be configured
		// in the repo-local .factory/settings.json, but the global config
		// at ~/.factory/settings.json might have other pre-existing entries).
		var settings droidSettings
		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
			// Best-effort merge: ignore parse errors and start fresh
			_ = json.Unmarshal(data, &settings)
		}

		// Replace or add the BYOK model entry.
		byokModel := droidCustomModel{
			DisplayName:    droidCustomModelDisplayName,
			Model:          droidCustomModelBaseID,
			BaseURL:        "https://api.anthropic.com",
			APIKey:         apiKey,
			Provider:       "anthropic",
			MaxOutputToken: 8192,
		}

		found := false
		for i, m := range settings.CustomModels {
			if m.Model == byokModel.Model {
				settings.CustomModels[i] = byokModel
				found = true
				break
			}
		}
		if !found {
			settings.CustomModels = append(settings.CustomModels, byokModel)
		}

		// Set the BYOK model as the default for interactive mode.
		if settings.SessionDefaultSettings == nil {
			settings.SessionDefaultSettings = &droidSessionDefaults{}
		}
		settings.SessionDefaultSettings.Model = droidCustomModelBaseID

		data, err := json.MarshalIndent(settings, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal settings: %w", err)
		}
		if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
			return fmt.Errorf("write settings: %w", err)
		}
	}

	cfg := droidStartupConfigFromEnv()
	if !cfg.warmup {
		return nil
	}
	if err := d.warmup(); err != nil {
		fmt.Fprintf(os.Stderr, "droid warmup failed (non-fatal): %v\n", err)
	}
	return nil
}

func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{Model: defaultDroidModel}
	for _, o := range opts {
		o(cfg)
	}

	model := cfg.Model
	if model == "" {
		model = defaultDroidModel
	}

	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}

	cmd := exec.CommandContext(ctx, d.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
	_ = ctx
	cfg := droidStartupConfigFromEnv()

	var s *TmuxSession
	var lastErr error
	handshakeRestartsLeft := cfg.handshakeRestarts
	for attempt := range cfg.attempts {
		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
		var err error
		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
		if err != nil {
			return nil, err
		}

		// Resize so droid's full-screen TUI has room to render the prompt area.
		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
		_ = exec.Command("tmux", "resize-window", "-t", name, "-x", "200", "-y", "50").Run()

		// Phase 1: detect startup readiness (prompt OR known startup markers).
		if _, err := s.WaitFor(droidStartupReadyPattern(), cfg.timeout); err != nil {
			_ = s.Close()
			if attempt < cfg.attempts-1 {
				lastErr = err
				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed during readiness wait: %s\n", attempt+1, cfg.attempts, err)
				time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
				continue
			}
			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, err)
		}

		// Phase 2: active handshake verifies the session can receive and answer prompts.
		handshakeOK := false
		for hAttempt := 1; hAttempt <= cfg.handshakeAttempts; hAttempt++ {
			token, err := d.performHandshake(s, cfg.handshakeTimeout)
			if err == nil {
				handshakeOK = true
				fmt.Fprintf(os.Stderr, "droid startup handshake succeeded on attempt %d/%d (token=%s)\n", hAttempt, cfg.handshakeAttempts, token)
				break
			}
			lastErr = err
			fmt.Fprintf(os.Stderr, "droid handshake attempt %d/%d failed: %v\n", hAttempt, cfg.handshakeAttempts, err)
		}
		if handshakeOK {
			s.stableAtSend = ""
			return s, nil
		}

		content := s.Capture()
		_ = s.Close()

		state := fmt.Sprintf("prompt=%t startup_markers=%t", droidPromptReady(content), droidStartupMarkersReady(content))
		wrappedErr := fmt.Errorf("startup handshake failed (%s): %w", state, lastErr)
		if handshakeRestartsLeft > 0 {
			handshakeRestartsLeft--
			lastErr = wrappedErr
			fmt.Fprintf(os.Stderr, "droid startup restarting session after handshake failure (%d restart(s) left): %v\n", handshakeRestartsLeft, wrappedErr)
			continue
		}
		if attempt < cfg.attempts-1 {
			lastErr = wrappedErr
			fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed after handshake retries: %v\n", attempt+1, cfg.attempts, wrappedErr)
			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
			continue
		}
		return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, wrappedErr)
	}
	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, lastErr)
}

func (d *Droid) performHandshake(s *TmuxSession, timeout time.Duration) (string, error) {
	token := droidHandshakeToken()
	if err := s.Send(droidHandshakePrompt(token)); err != nil {
		return token, fmt.Errorf("send handshake prompt: %w", err)
	}
	if _, err := s.WaitFor(regexp.QuoteMeta(token), timeout); err != nil {
		return token, fmt.Errorf("wait for handshake token: %w", err)
	}
	// Token echo proves droid is responsive. The WaitFor settle mechanism
	// (content changed from pre-Send + stabilized) ensures the response is
	// complete. No additional prompt pattern wait needed.
	return token, nil
}

func (d *Droid) warmup() error {
	const warmupAttempts = 2
	const warmupTimeout = 30 * time.Second

	dir, err := os.MkdirTemp("", "droid-warmup-*")
	if err != nil {
		return fmt.Errorf("create warmup dir: %w", err)
	}
	defer func() { _ = os.RemoveAll(dir) }()

	var lastErr error
	for attempt := range warmupAttempts {
		ctx, cancel := context.WithTimeout(context.Background(), warmupTimeout)
		out, err := d.RunPrompt(ctx, dir, "Reply with OK.", WithModel(defaultDroidModel))
		cancel()
		if err == nil {
			return nil
		}

		lastErr = fmt.Errorf("%w (stderr: %s)", err, strings.TrimSpace(out.Stderr))
		if attempt < warmupAttempts-1 && d.IsTransientError(out, err) {
			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
			continue
		}
		break
	}
	return lastErr
}

