)

func TestDroidStartupReadyPattern(t *testing.T) {
	t.Parallel()

	re, err := regexp.Compile(droidStartupReadyPattern())
	if err != nil {
		t.Fatalf("compile pattern: %v", err)
	}

	tests := []struct {
		name    string
		content string
		want    bool
	}{
		{
			name: "startup markers",
			content: `
ENTER to send • \\ + ENTER for a new line • @ to mention files
Current folder: /tmp/e2e-repo-123
`,
			want: true,
		},
		{
			name: "startup markers reversed order",
			content: `
Current folder: /tmp/e2e-repo-123
ENTER to send • \\ + ENTER for a new line
`,
			want: true,
		},
		{
			name: "splash only",
			content: `
█████████    █████████
You are standing in an open terminal. An AI awaits your commands.
`,
			want: false,
		},
		{
			name: "only ENTER to send without Current folder",
			content: `
ENTER to send • \\ + ENTER for a new line
`,
			want: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got := re.MatchString(tt.content)
			if got != tt.want {
				t.Fatalf("match=%v, want %v", got, tt.want)
			}
		})
	}
}

func TestDroidPromptPattern_DoesNotMatchAssistantMarker(t *testing.T) {
	t.Parallel()

	pattern := (&Droid{}).PromptPattern()
	assistantMarker := "⛬ I'll create the file now"
	if strings.Contains(assistantMarker, pattern) {
		t.Fatal("prompt pattern should not match assistant response marker")
	}
	statusBar := "ENTER to send • \\ + ENTER for a new line • @ to mention files"
	if !strings.Contains(statusBar, pattern) {
		t.Fatal("prompt pattern should match droid idle status bar")
	}
}

func TestDroidStartupConfigFromEnv_Defaults(t *testing.T) {
	t.Setenv("E2E_DROID_STARTUP_TIMEOUT", "")
	t.Setenv("E2E_DROID_STARTUP_ATTEMPTS", "")
	t.Setenv("E2E_DROID_WARMUP", "")
	t.Setenv("E2E_DROID_HANDSHAKE_TIMEOUT", "")
	t.Setenv("E2E_DROID_HANDSHAKE_ATTEMPTS", "")
	t.Setenv("E2E_DROID_HANDSHAKE_RESTARTS", "")
	t.Setenv("CI", "")

	cfg := droidStartupConfigFromEnv()

	if cfg.timeout != 60*time.Second {
		t.Fatalf("timeout=%s, want 60s", cfg.timeout)
	}
	if cfg.attempts != 2 {
		t.Fatalf("attempts=%d, want 2", cfg.attempts)
	}
	if cfg.warmup {
		t.Fatal("warmup=true, want false")
	}
	if cfg.handshakeTimeout != 45*time.Second {
		t.Fatalf("handshakeTimeout=%s, want 45s", cfg.handshakeTimeout)
	}
	if cfg.handshakeAttempts != 2 {
