337→func (s *RepoState) logPromptResult(out agents.Output) {
338→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
339→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
340→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
341→}
