350→// StartSession starts an interactive session and registers it for pane
351→// capture in artifacts. Returns nil if the agent does not support interactive
352→// mode. The session is closed automatically during test cleanup.
353→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
354→	t.Helper()
355→	session, err := s.Agent.StartSession(ctx, s.Dir)
356→	if err != nil {
357→		t.Fatalf("start session: %v", err)
358→	}
359→	if session == nil {
