452→// Git runs a git command in the given directory and fails the test if it
453→// returns a non-zero exit code.
454→func Git(t *testing.T, dir string, args ...string) {
455→	t.Helper()
456→
457→	cmd := exec.Command("git", args...)
458→	if dir != "" {
459→		cmd.Dir = dir
