func (d *Droid) warmup() error {
	const warmupAttempts = 2
	const warmupTimeout = 30 * time.Second

	dir, err := os.MkdirTemp("", "droid-warmup-*")
	if err != nil {
		return fmt.Errorf("create warmup dir: %w", err)
	}
	defer func() { _ = os.RemoveAll(dir) }()

	var lastErr error
	for attempt := range warmupAttempts {
		ctx, cancel := context.WithTimeout(context.Background(), warmupTimeout)
		out, err := d.RunPrompt(ctx, dir, "Reply with OK.", WithModel(defaultDroidModel))
		cancel()
		if err == nil {
			return nil
		}

		lastErr = fmt.Errorf("%w (stderr: %s)", err, strings.TrimSpace(out.Stderr))
		if attempt < warmupAttempts-1 && d.IsTransientError(out, err) {
			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
			continue
		}
		break
	}
	return lastErr
