// WaitFor waits for a pattern in the interactive session's pane and logs the
// pane content to ConsoleLog after the wait completes (success or failure).
func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
	t.Helper()
	scaled := time.Duration(float64(timeout) * s.Agent.TimeoutMultiplier())
	content, err := session.WaitFor(pattern, scaled)
	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
	if err != nil {
		if s.shouldUseDroidHandshakeRecovery(pattern) {
			t.Logf("WaitFor(%q) timed out; attempting droid handshake recovery", pattern)
			fmt.Fprintf(s.ConsoleLog, "> [recovery] attempting droid handshake after WaitFor(%q) timeout\n", pattern)
			content, recoveryErr := s.recoverDroidPromptTimeoutWithHandshake(session, pattern, scaled)
			fmt.Fprintf(s.ConsoleLog, "> pane after handshake recovery WaitFor(%q):\n%s\n", pattern, content)
			if recoveryErr == nil {
				return
			}
			err = fmt.Errorf("wait failed: %w; handshake recovery failed: %w", err, recoveryErr)
		}
		if err != nil {
			t.Fatalf("WaitFor(%q): %v", pattern, err)
		}
	}
}

func (s *RepoState) shouldUseDroidHandshakeRecovery(pattern string) bool {
	return s.Agent.Name() == "factoryai-droid" &&
		pattern == s.Agent.PromptPattern()
}

func (s *RepoState) recoverDroidPromptTimeoutWithHandshake(session agents.Session, _ string, timeout time.Duration) (string, error) {
	token := fmt.Sprintf("ENTIRE_E2E_READY_%d", time.Now().UnixNano())
	handshakePrompt := "E2E transport check. Reply with exactly this token and nothing else: " + token +
		". Do not edit files, run commands, or commit."

	fmt.Fprintf(s.ConsoleLog, "> [recovery] send handshake prompt with token %s\n", token)
	if err := session.Send(handshakePrompt); err != nil {
		return "", fmt.Errorf("send handshake prompt: %w", err)
	}

	content, err := session.WaitFor(regexp.QuoteMeta(token), timeout)
	fmt.Fprintf(s.ConsoleLog, "> pane after handshake token wait:\n%s\n", content)
	if err != nil {
		return content, fmt.Errorf("wait for handshake token: %w", err)
	}

	// Token echo proves the session is responsive. The WaitFor settle
	// mechanism ensures the response has stabilized. No additional prompt
	// pattern wait needed — it was the source of CI flakiness.
	return content, nil
}

