func (f *fakeSession) Send(input string) error {
	f.sendCalls = append(f.sendCalls, input)
	return nil
}

func (f *fakeSession) WaitFor(pattern string, _ time.Duration) (string, error) {
	f.waitCalls = append(f.waitCalls, pattern)
	if len(f.waitResponses) == 0 {
		return "", errors.New("unexpected wait call")
	}
	resp := f.waitResponses[0]
	f.waitResponses = f.waitResponses[1:]
	return resp.content, resp.err
}

func (f *fakeSession) Capture() string { return "" }
func (f *fakeSession) Close() error    { return nil }

func TestShouldUseDroidHandshakeRecovery(t *testing.T) {
	t.Parallel()

	droid := fakeAgent{name: "factoryai-droid", prompt: `ENTER to send`}
	s := &RepoState{Agent: droid}
	if !s.shouldUseDroidHandshakeRecovery(droid.prompt) {
		t.Fatal("expected droid prompt waits to use handshake recovery")
	}

	other := fakeAgent{name: "claude-code", prompt: `❯`}
	s = &RepoState{Agent: other}
	if s.shouldUseDroidHandshakeRecovery(other.prompt) {
		t.Fatal("did not expect non-droid agent to use handshake recovery")
	}
}

func TestRecoverDroidPromptTimeoutWithHandshake(t *testing.T) {
	t.Parallel()

	droid := fakeAgent{name: "factoryai-droid", prompt: `ENTER to send`}
	logFile, err := os.CreateTemp("", "repo-test-log-*.txt")
	if err != nil {
		t.Fatalf("create temp log: %v", err)
	}
	defer func() { _ = os.Remove(logFile.Name()) }()
	defer func() { _ = logFile.Close() }()

	s := &RepoState{Agent: droid, ConsoleLog: logFile}
	session := &fakeSession{
		waitResponses: []waitResponse{
			{content: "ENTIRE_E2E_READY_123", err: nil},
		},
	}

	content, err := s.recoverDroidPromptTimeoutWithHandshake(session, droid.prompt, 2*time.Second)
	if err != nil {
		t.Fatalf("recover handshake: %v", err)
	}
	if !strings.Contains(content, "ENTIRE_E2E_READY") {
		t.Fatalf("expected token echo content, got %q", content)
	}
	if len(session.sendCalls) != 1 {
		t.Fatalf("expected 1 handshake send, got %d", len(session.sendCalls))
	}
	if len(session.waitCalls) != 1 {
		t.Fatalf("expected 1 wait (token only), got %d", len(session.waitCalls))
	}

	tokenRe := regexp.MustCompile(`ENTIRE_E2E_READY_[0-9]+`)
	token := tokenRe.FindString(session.sendCalls[0])
	if token == "" {
		t.Fatalf("handshake prompt missing token: %q", session.sendCalls[0])
	}
	if session.waitCalls[0] != regexp.QuoteMeta(token) {
		t.Fatalf("first wait pattern = %q, want quoted token %q", session.waitCalls[0], regexp.QuoteMeta(token))
	}
}

func TestRecoverDroidPromptTimeoutWithHandshake_HandshakeFailure(t *testing.T) {
	t.Parallel()

	droid := fakeAgent{name: "factoryai-droid", prompt: `ENTER to send`}
	logFile, err := os.CreateTemp("", "repo-test-log-*.txt")
	if err != nil {
		t.Fatalf("create temp log: %v", err)
	}
	defer func() { _ = os.Remove(logFile.Name()) }()
	defer func() { _ = logFile.Close() }()

	s := &RepoState{Agent: droid, ConsoleLog: logFile}
	session := &fakeSession{
		waitResponses: []waitResponse{{content: "", err: errors.New("timeout")}},
	}

	_, err = s.recoverDroidPromptTimeoutWithHandshake(session, droid.prompt, 2*time.Second)
	if err == nil {
		t.Fatal("expected handshake recovery error")
	}
	if len(session.sendCalls) != 1 {
		t.Fatalf("expected 1 handshake send, got %d", len(session.sendCalls))
	}
}

func TestFakeAgentInterfaceParity(t *testing.T) {
	t.Parallel()
	var _ agents.Agent = fakeAgent{}
}

