  9→)
 10→
 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string   // stable content snapshot when Send was last called
 15→	cleanups     []func() // run on Close
 16→}
 17→
 18→// OnClose registers a function to run when the session is closed.
 19→func (s *TmuxSession) OnClose(fn func()) {
 20→	s.cleanups = append(s.cleanups, fn)
 21→}
 22→
 23→// NewTmuxSession creates a new tmux session running the given command in dir.
 24→// unsetEnv lists environment variable names to strip from the session.
 25→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 26→	s := &TmuxSession{name: name}
 27→
 28→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 29→	// Build a shell command string, prefixed with env -u for each var to strip.
 30→	// All arguments are shell-quoted to prevent injection or splitting.
 31→	var parts []string
 32→	for _, v := range unsetEnv {
 33→		parts = append(parts, "env", "-u", shellQuote(v))
 34→	}
 35→	parts = append(parts, shellQuote(command))
 36→	for _, a := range args {
 37→		parts = append(parts, shellQuote(a))
 38→	}
 39→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 40→
 41→	cmd := exec.Command("tmux", tmuxArgs...)
 42→	if out, err := cmd.CombinedOutput(); err != nil {
 43→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 44→	}
 45→	// Keep the pane around after the command exits so we can capture error output.
 46→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 47→	_ = setCmd.Run()
 48→	return s, nil
 49→}
 50→
 51→func (s *TmuxSession) Send(input string) error {
 52→	preSend := stableContent(s.Capture())
 53→	// Send text and Enter separately — Claude's TUI can swallow Enter
 54→	// if it arrives before the input handler finishes processing the text.
 55→	if err := s.SendKeys(input); err != nil {
 56→		return err
 57→	}
 58→	time.Sleep(200 * time.Millisecond)
 59→	if err := s.SendKeys("Enter"); err != nil {
 60→		return err
 61→	}
 62→
 63→	// Wait for the terminal to reflect the echoed input, then snapshot.
 64→	// This ensures WaitFor compares against post-echo content, preventing
 65→	// false matches on prompt characters (e.g. ❯) in the echoed input.
 66→	deadline := time.Now().Add(5 * time.Second)
 67→	for time.Now().Before(deadline) {
 68→		time.Sleep(200 * time.Millisecond)
 69→		current := stableContent(s.Capture())
 70→		if current != preSend {
 71→			s.stableAtSend = current
 72→			return nil
 73→		}
 74→	}
 75→	s.stableAtSend = stableContent(s.Capture())
 76→	return nil
 77→}
 78→
 79→// SendKeys sends raw tmux key names without appending Enter.
 80→func (s *TmuxSession) SendKeys(keys ...string) error {
 81→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 82→	cmd := exec.Command("tmux", args...)
 83→	out, err := cmd.CombinedOutput()
 84→	if err != nil {
 85→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 86→	}
 87→	return nil
 88→}
 89→
 90→const (
 91→	settleTime   = 2 * time.Second
 92→	pollInterval = 500 * time.Millisecond
 93→)
 94→
 95→// stableContent returns the content with the last few lines stripped,
 96→// so that TUI status bar updates don't prevent the settle timer.
 97→func stableContent(content string) string {
 98→	lines := strings.Split(content, "\n")
 99→	if len(lines) > 3 {
100→		lines = lines[:len(lines)-3]
101→	}
102→	return strings.Join(lines, "\n")
103→}
104→
105→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
106→	var re *regexp.Regexp
107→	if pattern != "" {
108→		var err error
109→		re, err = regexp.Compile(pattern)
110→		if err != nil {
111→			return "", fmt.Errorf("invalid pattern: %w", err)
112→		}
113→	}
114→
115→	deadline := time.Now().Add(timeout)
116→	var matchedAt time.Time
117→	var lastStable string
118→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
119→
120→	for time.Now().Before(deadline) {
121→		content := s.Capture()
122→		stable := stableContent(content)
123→
124→		if re != nil && !re.MatchString(content) {
125→			// Pattern lost — reset (only for pattern-based waits)
126→			matchedAt = time.Time{}
127→			lastStable = ""
128→			time.Sleep(pollInterval)
129→			continue
130→		}
131→
132→		// Detect content change since Send was called
133→		if !contentChanged && stable != s.stableAtSend {
134→			contentChanged = true
135→		}
136→
137→		if stable != lastStable {
138→			// Content is still changing — reset settle timer
139→			matchedAt = time.Now()
140→			lastStable = stable
141→			time.Sleep(pollInterval)
142→			continue
143→		}
144→
145→		// Content has stabilized (and matches pattern, if one was given).
146→		// Only settle if content changed at least once after Send
147→		// (prevents false settle on echoed input before agent starts).
148→		if contentChanged && time.Since(matchedAt) >= settleTime {
149→			return content, nil
150→		}
151→
152→		time.Sleep(pollInterval)
153→	}
154→	content := s.Capture()
155→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
156→}
157→
158→func (s *TmuxSession) Capture() string {
159→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
160→	out, _ := cmd.Output()
161→	return strings.TrimRight(string(out), "\n")
162→}
163→
164→func (s *TmuxSession) Close() error {
165→	for _, fn := range s.cleanups {
166→		fn()
167→	}
168→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
169→	out, err := cmd.CombinedOutput()
170→	if err != nil {
171→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
172→	}
173→	return nil
174→}
175→
176→// shellQuote wraps s in single quotes with proper escaping for POSIX shells.
177→func shellQuote(s string) string {
178→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
179→}
