251→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
252→	_ = ctx
253→	cfg := droidStartupConfigFromEnv()
254→
255→	var lastErr error
256→	for attempt := range cfg.attempts {
257→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
258→		s, err := NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
259→		if err != nil {
260→			return nil, err
261→		}
262→
263→		// Resize so droid's full-screen TUI has room to render the prompt area.
264→		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
265→		_ = exec.Command("tmux", "resize-window", "-t", name, "-x", "200", "-y", "50").Run()
266→
267→		// Wait for startup markers that prove droid has loaded.
268→		if _, err := s.WaitFor(droidStartupReadyPattern(), cfg.timeout); err != nil {
269→			_ = s.Close()
270→			lastErr = err
271→			if attempt < cfg.attempts-1 {
272→				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed: %s\n", attempt+1, cfg.attempts, err)
273→				time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
274→				continue
275→			}
276→			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, err)
277→		}
278→
279→		// Startup succeeded. Clear stableAtSend so the first WaitFor after
280→		// Send doesn't require a content change relative to startup content.
281→		s.stableAtSend = ""
282→		return s, nil
283→	}
284→	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, lastErr)
285→}
